package org.lira.receiver;
import java.nio.file.*;import java.io.*;import java.security.*;import org.json.*;import java.util.*;
/** Completion facts follow each lesson's required steps, not global task termination. */
public final class DictationCompletionTest {
 static JSONObject prepare(JSONObject task,TaskAssetStore assets)throws Exception {task.put("content_hash",DictationSpec.contentHash(task));Set<String> names=new HashSet<>(Arrays.asList("prompt.prepare","prompt.finish","prompt.pinyin","asset-yi"));JSONArray manifest=new JSONArray();byte[] pcm={0,0};StringBuilder sha=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(pcm))sha.append(String.format("%02x",b&255));for(String id:names){assets.begin(task.getString("task_id"),task.getString("content_hash"),id,2,sha.toString());assets.append(task.getString("task_id"),task.getString("content_hash"),id,0,pcm);assets.commit(task.getString("task_id"),task.getString("content_hash"),id);manifest.put(new JSONObject().put("asset_id",id).put("sha256",sha.toString()).put("pcm_bytes",2).put("frames",1).put("sample_rate",24000).put("channels",1));}return new JSONObject().put("task",task).put("manifest",new JSONObject().put("task_id",task.getString("task_id")).put("content_hash",task.getString("content_hash")).put("assets",manifest));}
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args)throws Exception {JSONObject original=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8"));for(boolean skip:new boolean[]{false,true}){JSONObject task=new JSONObject(original.toString());JSONObject first=task.getJSONArray("lessons").getJSONObject(0),second=new JSONObject(first.toString());second.put("lesson_id","second").put("two_targets",new JSONArray()).put("recognition_words",new JSONArray());task.getJSONArray("lessons").put(second);File dir=Files.createTempDirectory("completion").toFile();TaskAssetStore assets=new TaskAssetStore(new File(dir,"assets"));DictationEngineTest.Time time=new DictationEngineTest.Time();DictationEngineTest.Sound sound=new DictationEngineTest.Sound();DictationEngine e=new DictationEngine(time,sound,new DictationEngine.Display(){public void show(String k,JSONArray w,String t){}},new DictationStateStore(new File(dir,"state")),assets);e.start(prepare(task,assets));sound.drain();sound.drain();time.t+=30000;e.tick();check(e.status().getJSONArray("counted").length()==0,"first needs recognition");if(skip)e.control(DictationEngineTest.command(e,"skip"));else{sound.drain();time.t+=30000;e.tick();}check(e.status().getJSONArray("counted").length()==(skip?0:1),"four-only second completes before first recognition; skipped no fact");e.control(DictationEngineTest.command(e,"cancel"));check(e.status().getJSONArray("counted").length()==(skip?0:1),"cancel preserves prior complete");JSONArray events=e.pendingEvents();int complete=0;for(int i=0;i<events.length();i++)if(events.getJSONObject(i).getString("kind").equals("lesson_dictation_completed"))complete++;check(complete==(skip?0:1),"completion exact once");}
 System.out.println("Dictation per-lesson partial count, skipped item, interrupted task passed");}
}
